import json
import re

MANDATORY = {'"'"'"'"'"'"'"'"'opcache.enable'"'"'"'"'"'"'"'"': '"'"'"'"'"'"'"'"'1'"'"'"'"'"'"'"'"', '"'"'"'"'"'"'"'"'opcache.validate_permission'"'"'"'"'"'"'"'"': '"'"'"'"'"'"'"'"'1'"'"'"'"'"'"'"'"', '"'"'"'"'"'"'"'"'opcache.validate_root'"'"'"'"'"'"'"'"': '"'"'"'"'"'"'"'"'1'"'"'"'"'"'"'"'"', '"'"'"'"'"'"'"'"'opcache.restrict_api'"'"'"'"'"'"'"'"': '"'"'"'"'"'"'"'"'/etc/php-fpm/diagnostics/'"'"'"'"'"'"'"'"', '"'"'"'"'"'"'"'"'opcache.file_cache'"'"'"'"'"'"'"'"': '"'"'"'"'"'"'"'"''"'"'"'"'"'"'"'"', '"'"'"'"'"'"'"'"'opcache.preload'"'"'"'"'"'"'"'"': '"'"'"'"'"'"'"'"''"'"'"'"'"'"'"'"', '"'"'"'"'"'"'"'"'expose_php'"'"'"'"'"'"'"'"': '"'"'"'"'"'"'"'"'0'"'"'"'"'"'"'"'"'}


def _text(row: dict[str, object], key: str) -> str:
    value = row.get(key)
    return value if isinstance(value, str) and len(value) <= 32768 else ""


def live_values(
    row: dict[str, object], version: str
) -> tuple[dict[str, object], dict[str, object], list[str]] | None:
    response = _text(row, "response")
    header, separator, body = response.replace("\r\n", "\n").partition("\n\n")
    if not separator or any(
        line.lower().startswith("status:") and line.strip() != "Status: 200 OK"
        for line in header.splitlines()
    ):
        return None
    try:
        data: object = json.loads(body)
    except ValueError:
        return None
    if (
        not isinstance(data, dict)
        or set(data) != {"version", "sapi", "php", "parent", "uid", "extensions", "ini", "opcache"}
        or type(data["version"]) is not int
        or data["version"] != 1
        or type(data["parent"]) is not int
        or data["parent"] != row.get("master_pid")
        or data["sapi"] != "fpm-fcgi"
        or data["php"] != version
    ):
        return None
    identity = row.get("identity")
    if (
        not isinstance(identity, list)
        or len(identity) != 5
        or type(identity[0]) is not int
        or identity[0] <= 0
        or type(data.get("uid")) is not int
        or data["uid"] != identity[0]
    ):
        return None
    ini, opcache, raw_extensions = data["ini"], data["opcache"], data["extensions"]
    if (
        not isinstance(ini, dict)
        or not isinstance(opcache, dict)
        or not isinstance(raw_extensions, list)
        or len(raw_extensions) > 128
        or not all(
            isinstance(e, str) and re.fullmatch(r"[A-Za-z0-9_ -]{1,64}", e) for e in raw_extensions
        )
    ):
        return None
    return ini, opcache, raw_extensions


def protected(
    ini: dict[str, object], opcache: dict[str, object], extensions: tuple[str, ...]
) -> bool:
    if "Zend OPcache" not in extensions:
        return False
    for key, expected_value in MANDATORY.items():
        actual = ini.get(key)
        if key == "expose_php":
            if actual not in ("", "0"):
                return False
        elif actual != expected_value:
            return False
        if key != "expose_php":
            expected: object = True if expected_value == "1" else expected_value
            if opcache.get(key) != expected:
                return False
    return True


def master_identity(row: dict[str, object]) -> bool:
    expected = _text(row, "expected_executable")
    return (
        expected.startswith("/nix/store/")
        and expected.endswith("/bin/php-fpm")
        and _text(row, "master_executable") == expected
        and row.get("socket_owned") is True
        and row.get("load_safe") is True
        and row.get("same_invocation") is True
    )

"""The site identifier and DNS names an operator may request (docs/sites.md#names).

The form, the worker before any read and the payload builder each validate them again.
"""

import re
from collections.abc import Sequence

DISCOVERY_RESERVED = frozenset({"www", "html"})

IDENTIFIER = re.compile(r"[a-z][a-z0-9]{2,23}")
# docs/sites.md#names: the distribution'"'"'"'"'"'"'"'"'s own names, Barectl'"'"'"'"'"'"'"'"'s and the TLS convention'"'"'"'"'"'"'"'"'s.
RESERVED_IDENTIFIERS = DISCOVERY_RESERVED | frozenset(
    {
        "default",
        "php",
        "fpm",
        "nginx",
        "root",
        "admin",
        "localhost",
        "letsencrypt",
        "acme",
        "barectl",
        "apply",
        "site",
        "repo",
        "backup",
        "diagnostic",
    }
)
# docs/sites.md#names
SYSTEM_ACCOUNTS = frozenset(
    {
        "sshd",
        "syslog",
        "statd",
        "saned",
        "sssd",
        "snmp",
        "squid",
        "sddm",
        "stunnel4",
        "sasl",
        "sgx",
    }
)
MAX_NAMES = 10
# docs/sites.md#names: the longest name the stock server name hash admits.
MAX_NAME_OCTETS = 46
LABEL = re.compile(r"[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?")
RESERVED_NAMES = frozenset({"localhost", "invalid"})
_ALLOWED = re.compile(r"[A-Za-z0-9.-]+")


class InvalidInput(ValueError):
    def __init__(self, problems: Sequence[str]) -> None:
        super().__init__(" ".join(problems))
        self.problems = tuple(problems)


def valid_identifier(identifier: str) -> bool:
    """Whether ``identifier`` is a name Barectl may record or address."""
    return not identifier_problems(identifier)


def identifier_problems(identifier: str) -> list[str]:
    if not IDENTIFIER.fullmatch(identifier):
        return [
            "Enter 3 to 24 lowercase letters and digits, starting with a letter, such as shop2."
        ]
    if identifier in RESERVED_IDENTIFIERS or f"s{identifier}" in SYSTEM_ACCOUNTS:
        return [f"{identifier} is reserved; choose another identifier."]
    return []


def canonical_name(name: str, *, max_name_octets: int = MAX_NAME_OCTETS) -> tuple[str, str]:
    """The canonical form of one requested DNS name, or why it is refused."""
    if not name.isascii():
        return "", f"{name}: enter the punycode (xn--) form of an international name."
    if "*" in name:
        return "", f"{name}: wildcards are not supported; list each name."
    if not _ALLOWED.fullmatch(name):
        return "", f"{name}: use only letters, digits, hyphens and dots."
    canonical = name.lower().removesuffix(".")
    labels = canonical.split(".")
    if len(canonical) > max_name_octets:
        return "", f"{name}: names longer than {max_name_octets} characters are not supported."
    if len(labels) < 2 or not all(LABEL.fullmatch(label) for label in labels):
        return "", f"{name}: enter a fully qualified name such as www.example.com."
    if labels[-1].isdigit():
        return "", f"{name}: IP addresses are not supported; enter a DNS name."
    if labels[-1] in RESERVED_NAMES or canonical in RESERVED_NAMES:
        return "", f"{name}: {labels[-1]} names are reserved and never reach a server."
    for label in labels:
        problem = _label_problem(label)
        if problem:
            return "", f"{name}: {problem}"
    return canonical, ""


def _label_problem(label: str) -> str:
    if label[2:4] != "--":
        return ""
    if not label.startswith("xn--"):
        return f"{label} has hyphens in the third and fourth positions, reserved for punycode."
    try:
        decoded = label[4:].encode("ascii").decode("punycode")
        valid = not decoded.isascii() and decoded.encode("idna") == label.encode("ascii")
    except UnicodeError:
        valid = False
    return "" if valid else f"{label} is not valid punycode."


def names(text: str, *, max_name_octets: int = MAX_NAME_OCTETS) -> tuple[str, ...]:
    """The canonical names in ``text``, separated by whitespace, in the order given.

    Raises ``InvalidInput`` with every problem found.
    """
    requested = text.split()
    problems: list[str] = []
    found: list[str] = []
    for name in requested:
        canonical, problem = canonical_name(name, max_name_octets=max_name_octets)
        if problem:
            problems.append(problem)
        elif canonical in found:
            problems.append(f"{name}: listed more than once.")
        else:
            found.append(canonical)
    if not requested:
        problems.append("Enter at least one DNS name.")
    elif len(requested) > MAX_NAMES:
        problems.append(f"Enter at most {MAX_NAMES} names.")
    if problems:
        raise InvalidInput(problems)
    return tuple(found)


def request(
    identifier: str, text: str, *, max_name_octets: int = MAX_NAME_OCTETS
) -> tuple[str, tuple[str, ...]]:
    """A validated request, or ``InvalidInput`` with every problem found."""
    problems = identifier_problems(identifier)
    try:
        found = names(text, max_name_octets=max_name_octets)
    except InvalidInput as invalid:
        problems += invalid.problems
        found = ()
    if problems:
        raise InvalidInput(problems)
    return identifier, found

import configparser
import re
from typing import override


class PoolParser(configparser.ConfigParser):
    @override
    def optionxform(self, optionstr: str) -> str:
        return optionstr


def ini_pool(text: str, identifier: str) -> dict[str, str] | None:
    parser = PoolParser(interpolation=None, strict=True)
    try:
        parser.read_string(text)
        if parser.defaults() or parser.sections() != [identifier]:
            return None
        return dict(parser[identifier])
    except configparser.Error:
        return None


def safe_pool_boundary(identifier: str, runtime: str, text: str) -> bool:
    if identifier == "diagnostic" or re.fullmatch(r"[a-z][a-z0-9]{2,23}", identifier) is None:
        return False
    values = ini_pool(text, identifier)
    if values is None:
        return False
    fixed = {
        "user": "s" + identifier,
        "group": "s" + identifier,
        "listen": f"/run/php-fpm/{runtime}/{identifier}.sock",
    }
    if any(values.get(key) != value for key, value in fixed.items()):
        return False
    return not any(
        key.split("[", 1)[0].lower() == "include" or "opcache." in key.lower() for key in values
    )

